import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import axios from "axios";

function Perfil() {
  const { id } = useParams();
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    axios.get(`http://localhost:3001/usuarios/${id}`)
      .then(res => setUsuario(res.data))
      .catch(err => console.error("Erro ao buscar usuário:", err));
  }, [id]);

  if (!usuario) return <p>Carregando...</p>;

  return (
    <div className="card p-4">
      <h4>{usuario.nome}</h4>
      <p><strong>Idade:</strong> {usuario.idade}</p>
      <p><strong>Endereço:</strong> {usuario.rua}, {usuario.bairro}, {usuario.estado}</p>
      <p><strong>Biografia:</strong> {usuario.biografia}</p>
      {usuario.imagem && (
        <img
          src={`http://localhost:3001${usuario.imagem}`}
          alt="Foto do usuário"
          width="150"
          style={{ borderRadius: "8px", objectFit: "cover" }}
        />
      )}

      <div className="mt-3">
        <Link to={`/editar/${usuario.id}`} className="btn btn-warning">
          Editar Perfil
        </Link>
      </div>
    </div>
  );
}

export default Perfil;
